#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(DESeq2);library(SummarizedExperiment);library(ggplot2)})
repo<-normalizePath(Sys.getenv('WS40_REPO',unset='.'));out<-file.path(repo,'results/reproduced/figures/pca');dir.create(out,recursive=TRUE,showWarnings=FALSE)
se<-readRDS(file.path(repo,'data/input/WS40_12dpd_original_SE.rds'));se<-se[rowSums(assay(se))>=5,];se$treatment<-factor(se$treatment,levels=c('t0','SA','LA','SR','LR'));dds<-DESeqDataSet(se,design=~treatment);vsd<-vst(dds,blind=FALSE);pca<-plotPCA(vsd,intgroup='treatment',returnData=TRUE);pct<-round(100*attr(pca,'percentVar'));labs<-c(t0='Normoxia',SA='4hA',LA='24hA',SR='2hR',LR='24hR');pca$group<-factor(labs[as.character(pca$treatment)],levels=unname(labs));pal<-c(Normoxia='#E69F00','4hA'='#D55E00','24hA'='#009E73','2hR'='#0072B2','24hR'='#CC79A7');g<-ggplot(pca,aes(PC1,PC2,color=group))+geom_point(size=3)+scale_color_manual(values=pal)+labs(x=paste0('PC1: ',pct[1],'%'),y=paste0('PC2: ',pct[2],'%'),color='Condition')+theme_classic(base_size=10)+theme(legend.position='bottom');ggsave(file.path(out,'PCA_12dpd.png'),g,width=4.5,height=3.5,dpi=600);ggsave(file.path(out,'PCA_12dpd.pdf'),g,width=4.5,height=3.5);write.csv(pca,file.path(out,'PCA_12dpd_coordinates.csv'),row.names=FALSE)
